        # Bring u up to depth of v
        for k in range(LOG-1, -1, -1):
            if depth[u] - (1 << k) >= depth[v]:
                u = up[k][u]
        if u == v:
            return u
        for k in range(LOG-1, -1, -1):
            if up[k][u] != up[k][v]:
                u = up[k][u]
                v = up[k][v]
        return parent[u]

    def get_path_color_counts(u, v):
        ancestor = lca(u, v)
        red_u = color_count[u][0] - color_count[ancestor][0]
        black_u = color_count[u][1] - color_count[ancestor][1]
        red_v = color_count[v][0] - color_count[ancestor][0]
        black_v = color_count[v][1] - color_count[ancestor][1]
        return (red_u + red_v, black_u + black_v)

    def get_path_product(u, v):
        ancestor = lca(u, v)
