                    product = (product * x) % MOD
                    break
        # Path from v to ancestor
        while v != ancestor:
            for k in range(LOG-1, -1, -1):
                if depth[v] - (1 << k) >= depth[ancestor]:
                    v = up[k][v]
            # Find the edge from parent[v] to v
            for (v_edge, x, c) in adj[parent[v]]:
                if v_edge == v:
                    product = (product * x) % MOD
                    break
        return product

